import{_ as l,a0 as t,w as r,s as d,ao as p,I as o,a1 as i,A as e,x as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"moro：一個用於追蹤工作時間的命令列生產力工具 | LCTT x X-CMD","titleTemplate":false,"description":"moro：一個用於追蹤工作時間的命令列生產力工具 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"moro：一個用於追蹤工作時間的命令列生產力工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"moro：一個用於追蹤工作時間的命令列生產力工具 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180319 A Command Line Productivity Tool For Tracking Work Hours","title":"moro：一個用於追蹤工作時間的命令列生產力工具","tag":"201805","desc":""},"relativePath":"201805/20180319 A Command Line Productivity Tool For Tracking Work Hours.md","filePath":"[post].md"}'),h={name:"201805/20180319 A Command Line Productivity Tool For Tracking Work Hours.md"};function c(k,s,g,u,b,m){const n=t("Link");return r(),d("div",null,[s[14]||(s[14]=p('<h1 id="moro-一個用於追蹤工作時間的命令列生產力工具" tabindex="-1">moro：一個用於追蹤工作時間的命令列生產力工具 <a class="header-anchor" href="#moro-一個用於追蹤工作時間的命令列生產力工具" aria-label="Permalink to “moro：一個用於追蹤工作時間的命令列生產力工具”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/03/Moro-720x340.jpg" alt=""></p><p>保持對你的工作小時數的追蹤將讓你知曉在一個特定時間區間內你所完成的工作總量。在網絡上有大量的基於 GUI 的生產力工具可以用來追蹤工作小時數。但我卻不能找到一個基於 CLI 的工具。今天我偶然發現了一個簡單而奏效的叫做 Moro 的追蹤工作時間數的工具。Moro 是一個芬蘭詞彙，意為“Hello”。通過使用 Moro，你可以找到你在完成某項特定任務時花費了多少時間。這個工具是自由開源軟件，它是通過 NodeJS 編寫的。</p><h3 id="moro-一個追蹤工作時間的命令列生產力工具" tabindex="-1">Moro - 一個追蹤工作時間的命令列生產力工具 <a class="header-anchor" href="#moro-一個追蹤工作時間的命令列生產力工具" aria-label="Permalink to “Moro - 一個追蹤工作時間的命令列生產力工具”">​</a></h3><p>由於 Moro 是使用 NodeJS 編寫的，保證你的系統上已經安裝了 NodeJS。如果你沒有安裝好 NodeJS，跟隨下面的鏈接在你的 Linux 中安裝 NodeJS 和 NPM。</p>',5)),o("ul",null,[o("li",null,[i(n,{href:"https://www.ostechnix.com/install-node-js-linux/"},{default:e(()=>[...s[0]||(s[0]=[a("如何在 Linux 上安裝 NodeJS",-1)])]),_:1})])]),s[15]||(s[15]=p(`<p>NodeJS 和NPM一旦裝好，運行下面的命令來安裝 Moro。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ npm install -g moro</span></span></code></pre></div><h3 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h3><p>Moro 的工作概念非常簡單。它記錄了你的工作開始時間，結束時間和在你的系統上的休息時間。在每天結束時，它將會告知你已經工作了多少時間。</p><p>當你到達辦公室時，只需鍵入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ moro</span></span></code></pre></div><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>♥ Moro \\o/</span></span>
<span class="line"><span>√ You clocked in at: 9:20</span></span></code></pre></div><p>Moro 將會把這個時間註冊為你的開始時間。</p><p>當你離開辦公室時，再次鍵入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ moro</span></span></code></pre></div><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>♥ Moro \\o/</span></span>
<span class="line"><span>√ You clocked out at: 19:22</span></span>
<span class="line"><span>ℹ Today looks like this so far:</span></span>
<span class="line"><span>┌──────────────────┬─────────────────────────┐</span></span>
<span class="line"><span>│ Today you worked │ 9 Hours and 72 Minutes │</span></span>
<span class="line"><span>├──────────────────┼─────────────────────────┤</span></span>
<span class="line"><span>│ Clock in │ 9:20 │</span></span>
<span class="line"><span>├──────────────────┼─────────────────────────┤</span></span>
<span class="line"><span>│ Clock out │ 19:22 │</span></span>
<span class="line"><span>├──────────────────┼─────────────────────────┤</span></span>
<span class="line"><span>│ Break duration │ 30 minutes │</span></span>
<span class="line"><span>├──────────────────┼─────────────────────────┤</span></span>
<span class="line"><span>│ Date │ 2018-03-19 │</span></span>
<span class="line"><span>└──────────────────┴─────────────────────────┘</span></span>
<span class="line"><span>ℹ Run moro --help to learn how to edit your clock in, clock out or break duration for today</span></span></code></pre></div><p>Moro 將會把這個時間註冊為你的結束時間。</p><p>現在，Moro 將會從結束時間減去開始時間，然後從總的時間減去另外的 30 分鐘作為休息時間，並給你在那天總的工作時間。抱歉，我的數學計算過程解釋實在糟糕。假設你在早上 10:00 來工作並在晚上 17:30 離開。所以，你總共在辦公室呆了 7:30 小時（例如 17:30-10）。然後在總的時間減去休息時間（默認是 30 分鐘）。因此，你的總工作時間是 7 小時。明白了？很好！</p><p><strong>注意：</strong>不要像我在寫這個手冊的時候一樣把 “moro” 和 “more” 弄混了。</p><p>查看你註冊的所有小時數，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ moro report --all</span></span></code></pre></div><p>以防萬一，如果你忘記註冊開始時間或者結束時間，你一樣可以在之後指定這些值。</p><p>例如，將上午 10 點註冊為開始時間，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ moro hi 10:00</span></span>
<span class="line"><span>♥ Moro \\o/</span></span>
<span class="line"><span>√ You clocked in at: 10:00</span></span>
<span class="line"><span>⏰ Working until 18:00 will make it a full (7.5 hours) day</span></span></code></pre></div><p>註冊 17:30 作為結束時間：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ moro bye 17:30</span></span>
<span class="line"><span>♥ Moro \\o/</span></span>
<span class="line"><span>√ You clocked out at: 17:30</span></span>
<span class="line"><span>ℹ Today looks like this so far:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>┌──────────────────┬───────────────────────┐</span></span>
<span class="line"><span>│ Today you worked │ 7 Hours and 0 Minutes │</span></span>
<span class="line"><span>├──────────────────┼───────────────────────┤</span></span>
<span class="line"><span>│ Clock in │ 10:00 │</span></span>
<span class="line"><span>├──────────────────┼───────────────────────┤</span></span>
<span class="line"><span>│ Clock out │ 17:30 │</span></span>
<span class="line"><span>├──────────────────┼───────────────────────┤</span></span>
<span class="line"><span>│ Break duration │ 30 minutes │</span></span>
<span class="line"><span>├──────────────────┼───────────────────────┤</span></span>
<span class="line"><span>│ Date │ 2018-03-19 │</span></span>
<span class="line"><span>└──────────────────┴───────────────────────┘</span></span>
<span class="line"><span>ℹ Run moro --help to learn how to edit your clock in, clock out or break duration for today</span></span></code></pre></div><p>你已經知道 Moro 默認將會減去 30 分鐘的休息時間。如果你需要設置一個自定義的休息時間，你可以簡單使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ moro break 45</span></span></code></pre></div><p>現在，休息時間是 45 分鐘了。</p><p>若要清除所有的數據：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ moro clear --yes</span></span>
<span class="line"><span>♥ Moro \\o/</span></span>
<span class="line"><span>√ Database file deleted successfully</span></span></code></pre></div><h4 id="添加筆記" tabindex="-1">添加筆記 <a class="header-anchor" href="#添加筆記" aria-label="Permalink to “添加筆記”">​</a></h4><p>有時候，你想要在工作時添加筆記。不必去尋找一個獨立的作筆記的應用。Moro 將會幫助你添加筆記。要添加筆記，只需運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ moro note mynotes</span></span></code></pre></div><p>要在之後搜索所有已經註冊的筆記，只需做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ moro search mynotes</span></span></code></pre></div><h4 id="修改默認設置" tabindex="-1">修改默認設置 <a class="header-anchor" href="#修改默認設置" aria-label="Permalink to “修改默認設置”">​</a></h4><p>默認的完整工作時間是 7.5 小時。這是因為開發者來自芬蘭，這是官方的工作小時數。但是你也可以修改這個設置為你的國家的工作小時數。</p><p>舉個例子，要將其設置為 7 小時，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ moro config --day 7</span></span></code></pre></div><p>同樣地，默認的休息時間也可以像下面這樣從 30 分鐘修改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ moro config --break 45</span></span></code></pre></div><h4 id="備份你的數據" tabindex="-1">備份你的數據 <a class="header-anchor" href="#備份你的數據" aria-label="Permalink to “備份你的數據”">​</a></h4><p>正如我已經説了的，Moro 將時間追蹤信息存儲在你的家目錄，文件名是 <code>.moro-data.db</code>。</p><p>但是，你可以保存備份資料庫到不同的位置。要這樣做的話，像下面這樣將 <code>.moro-data.db</code> 文件移到你選擇的一個不同的位置並告知 Moro 使用那個資料庫文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ moro config --database-path /home/sk/personal/moro-data.db</span></span></code></pre></div><p>在上面的每一個命令，我都已經把默認的資料庫文件分配到了 <code>/home/sk/personal</code> 目錄。</p><p>需要幫助的話，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ moro --help</span></span></code></pre></div><p>正如你所見，Moro 是非常簡單而又能用於追蹤你完成你的工作使用了多少時間的。對於自由職業者和任何想要在一定時間範圍內完成事情的人，它將會是有用的。</p><p>並且，這些只是今天的內容。希望這些內容能夠有所幫助。更多的好東西將會出現。請保持關注！</p><p>乾杯！</p><hr>`,50)),o("p",null,[s[2]||(s[2]=a("via: ",-1)),i(n,{href:"https://www.ostechnix.com/moro-a-command-line-productivity-tool-for-tracking-work-hours/"},{default:e(()=>[...s[1]||(s[1]=[a("https://www.ostechnix.com/moro-a-command-line-productivity-tool-for-tracking-work-hours/",-1)])]),_:1})]),o("p",null,[s[6]||(s[6]=a("作者：",-1)),i(n,{href:"https://www.ostechnix.com/author/sk/"},{default:e(()=>[...s[3]||(s[3]=[a("SK",-1)])]),_:1}),s[7]||(s[7]=a(" 譯者：",-1)),i(n,{href:"https://github.com/leemeans"},{default:e(()=>[...s[4]||(s[4]=[a("leemeans",-1)])]),_:1}),s[8]||(s[8]=a(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:e(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),o("p",null,[s[11]||(s[11]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[9]||(s[9]=[a("LCTT",-1)])]),_:1}),s[12]||(s[12]=a(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:e(()=>[...s[10]||(s[10]=[a("Linux中國",-1)])]),_:1}),s[13]||(s[13]=a(" 榮譽推出",-1))])])}const x=l(h,[["render",c]]);export{C as __pageData,x as default};
